cat /tmp/searching.json | python3 -c "
import json, sys
data = json.load(sys.stdin)

def get_text(content):
    if isinstance(content, list):
        return ''.join(get_text(c) for c in content)
    if isinstance(content, dict):
        if content.get('type') == 'text':
            return content.get('text','')
        if content.get('type') == 'reference':
            ot = content.get('overridingTitle')
            if ot: return ot
            ic = content.get('overridingTitleInlineContent')
            if ic: return get_text(ic)
            return ''
        if content.get('type') == 'codeVoice':
            return content.get('code','')
        if 'inlineContent' in content:
            return get_text(content['inlineContent'])
        if 'content' in content:
            return get_text(content['content'])
    return ''

def walk(content, depth=0):
    if isinstance(content, list):
        for item in content:
            walk(item, depth)
    elif isinstance(content, dict):
        t = content.get('type', content.get('kind', ''))
        if t == 'heading':
            print()
            print('### L'+str(content.get('level'))+': ', content.get('text'))
        elif t == 'paragraph':
            txt = get_text(content)
            if txt.strip():
                print('PARA:', txt[:600])
        elif t in ('unorderedList','orderedList'):
            for li in content.get('items', []):
                txt = get_text(li.get('content', []))
                if txt.strip():
                    print(' - ', txt[:400])
        elif 'content' in content:
            walk(content['content'], depth)

for sec in data.get('primaryContentSections', []):
    walk(sec)
